challenge.verificationSource:
mod solution;

fn main() {
    assert_eq!(solution::initials("ada lovelace"), "AL", "case 1");
    assert_eq!(solution::initials("  grace   hopper "), "GH", "case 2");
    assert_eq!(solution::initials("élodie durand"), "ÉD", "case 3");
    assert_eq!(solution::initials("𝒜da lovelace"), "𝒜L", "case 4");
    assert_eq!(solution::initials("ßen x"), "SSX", "case 5");
    assert_eq!(solution::initials(""), "", "case 6");

    println!("PASS node-utf16-strings-to-utf8");
}
